import "C"

type JNIBridge struct {
	mu          sync.Mutex
	initialized atomic.Bool
	envCache    sync.Map
	keyMaterial []byte
	refCount    int64
}

type envHandle struct {
	env    *C.JNIEnv
	pinned bool
	tid    int64
}

var globalBridge *JNIBridge
var bridgeOnce sync.Once

func GetBridge() *JNIBridge {
	bridgeOnce.Do(func() {
		key := make([]byte, 32)
		// Seed with cryptographically secure random key material instead of
		// leaving an all-zero, predictable key.
		if _, err := rand.Read(key); err != nil {
			panic(fmt.Sprintf("failed to generate key material: %v", err))
		}
		globalBridge = &JNIBridge{
			keyMaterial: key,
		}
	})
	return globalBridge
}

func (b *JNIBridge) Initialize() error {
	b.mu.Lock()
	defer b.mu.Unlock()
	if b.initialized.Load() {
		return nil
	}
	rc := C.initJVM()
	if rc != 0 {
		return fmt.Errorf("JVM init failed: %d", rc)
	}
	b.initialized.Store(true)
	return nil
}

func (b *JNIBridge) getEnv() *envHandle {
	tid := getGoroutineID()
	if cached, ok := b.envCache.Load(tid); ok {
		return cached.(*envHandle)
	}
	env := C.attachThread()
	h := &envHandle{env: env, pinned: false, tid: tid}
	b.envCache.Store(tid, h)
	atomic.AddInt64(&b.refCount, 1)
	return h
}

func (b *JNIBridge) releaseEnv(h *envHandle) {
	if !h.pinned {
		b.envCache.Delete(h.tid)
		C.detachThread()
		atomic.AddInt64(&b.refCount, -1)
	}
}

// EncryptAsync performs JNI-backed encryption with goroutine scheduling awareness
func (b *JNIBridge) EncryptAsync(ctx context.Context, plaintext []byte) (<-chan []byte, <-chan error) {
	resultCh := make(chan []byte, 1)
	errCh := make(chan error, 1)

	go func() {
		defer close(resultCh)
		defer close(errCh)

		select {
		case <-ctx.Done():
			errCh <- ctx.Err()
			return
		default:
		}

		// Validate inputs before crossing the JNI boundary to avoid
		// dereferencing element zero of an empty slice.
		if len(plaintext) == 0 {
			errCh <- fmt.Errorf("plaintext must not be empty")
			return
		}
		if len(b.keyMaterial) == 0 {
			errCh <- fmt.Errorf("key material not initialized")
			return
		}

		// Pin goroutine to OS thread for entire JNI interaction
		runtime.LockOSThread()
		defer runtime.UnlockOSThread()

		h := b.getEnv()
		defer b.releaseEnv(h)

		// Create pinned copies for JNI boundary crossing
		dataCopy := make([]byte, len(plaintext))
		copy(dataCopy, plaintext)

		keyCopy := make([]byte, len(b.keyMaterial))
		copy(keyCopy, b.keyMaterial)

		dataPtr := unsafe.Pointer(&dataCopy[0])
		keyPtr := unsafe.Pointer(&keyCopy[0])

		result := C.encryptPayload(
			h.env,
			dataPtr,
			C.int(len(dataCopy)),
			keyPtr,
			C.int(len(keyCopy)),
		)

		if result == nil {
			errCh <- fmt.Errorf("encryption failed")
			return
		}

		// Extract result bytes - OS thread is still locked, env is valid
		resLen := C.(*h.env).GetArrayLength(h.env, result)
		goResult := make([]byte, int(resLen))
		if resLen > 0 {
			C.(*h.env).GetByteArrayRegion(h.env, result, 0, resLen, (*C.jbyte)(unsafe.Pointer(&goResult[0])))
		}
		C.(*h.env).DeleteLocalRef(h.env, result)

		resultCh <- goResult
	}()

	return resultCh, errCh
}

func getGoroutineID() int64 {
	var buf [64]byte
	n := runtime.Stack(buf[:], false)
	var id int64
	fmt.Sscanf(string(buf[:n]), "goroutine %d ", &id)
	return id
}
